from collections import deque

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    if start == goal:
        return [start]  # If start is the goal, return the start node as a single-element array

    # Dictionary to keep track of visited nodes
    visited = {}
    for node in graph:
        visited[node] = False

    # List to keep track of the path
    path = []

    # Queue for BFS
    queue = deque([(start, [start])])  # (node, path)

    while queue:
        current_node, path = queue.popleft()

        if current_node == goal:
            return path  # if current_node is goal, return the path

        visited[current_node] = True

        for neighbor in graph[current_node]:
            if not visited[neighbor]:
                queue.append((neighbor, path + [neighbor]))  # add neighbor to queue with extended path

    return None  # No path found

